class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        int top = *max_element(nums.begin(), nums.end());
        vector<int> points(top + 1, 0);
        for (int x : nums) points[x] += x;
        int take = 0, skip = 0;
        for (int v = 0; v <= top; v++) {
            int nt = skip + points[v];
            skip = max(skip, take);
            take = nt;
        }
        return max(take, skip);
    }
};
